const test=require('node:test');const assert=require('node:assert/strict');const fs=require('node:fs');
const app=fs.readFileSync('app.js','utf8'),css=fs.readFileSync('styles.css','utf8');
test('5.7.0 reconstruye Hablar sin posicionar el panel como fixed',()=>{assert.match(app,/prototipo-5\.7\.1-talk-fullscreen/);const fn=app.slice(app.indexOf('function fitTalkWindow'),app.indexOf('function navIndex'));assert.doesNotMatch(fn,/setProperty\('position','fixed'/);assert.match(css,/5\.7\.0 — reconstrucción de Hablar desde cero/);assert.match(css,/grid-template-rows:auto minmax\(0,1fr\) auto/)});
test('mensajes son el único scroll y compositor vive en el grid',()=>{const tail=css.slice(css.indexOf('5.7.0 — reconstrucción'));assert.match(tail,/\.talk-thread[\s\S]*overflow-y:auto!important/);assert.match(tail,/\.composer-wrap[\s\S]*position:relative!important/);assert.match(tail,/touch-action:pan-y!important/)});
